import os
import re
from datetime import datetime, date, timedelta
import csv

REF_DATE = date(2025, 8, 12)

def is_today(d):
    return d == REF_DATE

def is_last_7_days(d):
    return (REF_DATE - timedelta(days=6)) <= d <= REF_DATE

def is_last_30_days(d):
    return (REF_DATE - timedelta(days=29)) <= d <= REF_DATE

def is_month_to_date(d):
    return date(REF_DATE.year, REF_DATE.month, 1) <= d <= REF_DATE

def is_total(d):
    return True

periods = [
    ('today', is_today),
    ('last_7_days', is_last_7_days),
    ('last_30_days', is_last_30_days),
    ('month_to_date', is_month_to_date),
    ('total', is_total),
]

severities = ['ERROR', 'WARNING', 'INFO']

counts = {p_name: {s: 0 for s in severities} for p_name, _ in periods}

log_dir = '/app/logs'
for fname in os.listdir(log_dir):
    if not fname.endswith('.log'):
        continue
    file_date_str = fname.split('_')[0]
    try:
        fdate = datetime.strptime(file_date_str, '%Y-%m-%d').date()
    except ValueError:
        continue

    filepath = os.path.join(log_dir, fname)
    with open(filepath, 'r', encoding='utf-8') as f:
        for line in f:
            m = re.search(r'\[(ERROR|WARNING|INFO)\]', line)
            if m:
                sev = m.group(1)
                for p_name, p_filter in periods:
                    if p_filter(fdate):
                        counts[p_name][sev] += 1

output_file = '/app/summary.csv'
with open(output_file, 'w', newline='', encoding='utf-8') as csvfile:
    writer = csv.writer(csvfile)
    writer.writerow(['period', 'severity', 'count'])
    for p_name, _ in periods:
        for sev in severities:
            writer.writerow([p_name, sev, counts[p_name][sev]])

print('Summary generated successfully:')
with open(output_file, 'r') as csvfile:
    print(csvfile.read())
